import "../../styles/index-base.css";
import "../../styles/components/menu.css";
import { Menu as MenuPrimitive } from "@base-ui/react/menu";
import { Check } from "@phosphor-icons/react";
import type { HTMLAttributes } from "react";
import { cn } from "../../lib/cn";

export const Menu = MenuPrimitive.Root;

export function MenuTrigger(props: MenuPrimitive.Trigger.Props) {
  return <MenuPrimitive.Trigger data-slot="menu-trigger" {...props} />;
}

type MenuContentProps = MenuPrimitive.Popup.Props &
  Pick<MenuPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

export function MenuContent({ className, align = "start", alignOffset = 0, side = "bottom", sideOffset = 6, ...props }: MenuContentProps) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner className="ix-positioner" align={align} alignOffset={alignOffset} side={side} sideOffset={sideOffset}>
        <MenuPrimitive.Popup className={cn("ix-menu", className)} {...props} data-layer="flyout" />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  );
}

export function MenuLabel({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div role="presentation" className={cn("ix-menu__label", className)} {...props} />;
}

export function MenuItem({ className, ...props }: MenuPrimitive.Item.Props) {
  return <MenuPrimitive.Item className={cn("ix-menu__item", className)} {...props} />;
}

export function MenuSeparator(props: MenuPrimitive.Separator.Props) {
  return <MenuPrimitive.Separator className="ix-menu__separator" {...props} />;
}

export function MenuCheckboxItem({ className, children, ...props }: MenuPrimitive.CheckboxItem.Props) {
  return (
    <MenuPrimitive.CheckboxItem className={cn("ix-menu__item ix-menu__item--check", className)} {...props}>
      <span>{children}</span>
      <MenuPrimitive.CheckboxItemIndicator className="ix-menu__check"><Check weight="bold" /></MenuPrimitive.CheckboxItemIndicator>
    </MenuPrimitive.CheckboxItem>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-positioner { z-index: var(--ix-layer-flyout); }

.ix-menu kbd { font-family: inherit; font-size: 10px; color: var(--ix-ink-tertiary); }

.ix-menu { min-width: 196px; max-height: var(--available-height); padding: 4px; overflow: auto; border-radius: var(--ix-radius-overlay); background: var(--ix-bg-flyout); box-shadow: var(--ix-shadow-flyout); outline: 0; transform-origin: var(--transform-origin); transition: opacity 150ms var(--ix-ease-out), transform 150ms var(--ix-ease-out); }

.ix-menu[data-starting-style] { opacity: 0; transform: translateY(-2px) scale(0.985); }

.ix-menu[data-ending-style] { opacity: 0; transform: translateY(-1px) scale(0.99); transition-duration: 100ms; }

.ix-menu__label { padding: 6px 7px 4px; color: var(--ix-ink-tertiary); font-size: 11.5px; font-weight: 560; letter-spacing: 0.02em; }

.ix-menu__item { display: flex; min-height: var(--ix-row-height-menu); align-items: center; gap: 7px; padding: 0 7px; border-radius: calc(var(--ix-radius-control) - 1px); outline: 0; color: var(--ix-ink); font-size: 13px; cursor: default; user-select: none; }

.ix-menu__item svg { width: 13px; height: 13px; color: var(--ix-fg-muted); }

.ix-menu__item kbd { margin-left: auto; }

.ix-menu__item[data-highlighted] { background: var(--ix-hover); color: var(--ix-ink); }

.ix-menu__item[data-disabled] { opacity: 0.4; }

.ix-menu__item--check { justify-content: space-between; }

.ix-menu__check { display: inline-flex; }

.ix-menu__check svg { width: 11px; height: 11px; color: currentColor; }

.ix-menu__separator { height: 1px; margin: 4px; background: var(--ix-border-subtle); }

.ix-menu {
  scrollbar-color: var(--ix-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.ix-menu::-webkit-scrollbar { width: 10px; height: 10px; }

.ix-menu::-webkit-scrollbar-track { background: transparent; }

.ix-menu::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--ix-scrollbar-thumb);
  background-clip: padding-box;
}

.ix-menu::-webkit-scrollbar-thumb:hover { background: var(--ix-scrollbar-thumb-hover); background-clip: padding-box; }

:root[data-theme="dark"] .ix-menu__item svg,
:root[data-theme="dark"] .ix-menu__check svg { color: var(--ix-ink); }

.ix-menu__check {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--ix-ease-out), transform 140ms var(--ix-ease-out);
}

@starting-style {
.ix-menu__check {
    opacity: 0;
    transform: scale(.72);
  }
}

@media (prefers-reduced-motion: reduce) {
.ix-menu__check { transition-duration: 0.01ms; }
}

.ix-menu { background: var(--ix-bg-flyout); }

@media (forced-colors: active) {
.ix-menu { scrollbar-color: auto; }
}

@media (prefers-reduced-motion: reduce) {
.ix-menu {
    transition-property: opacity;
    transition-duration: var(--ix-exit-duration);
  }

.ix-menu[data-starting-style],
.ix-menu[data-ending-style] { transform: none; }

.ix-menu__check { transition-duration: 0.01ms; }
}
}
